    """Find connected components using 4-connectivity"""
    visited = set()
    components = []

    eight_set = set(eight_positions)

    def get_neighbors(pos):
        r, c = pos
        neighbors = [(r+dr, c+dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]]
        return [p for p in neighbors if p in eight_set]

    for start in eight_positions:
        if start in visited:
            continue
        # BFS
        comp = []
        queue = deque([start])
        while queue:
            pos = queue.popleft()
